 id: 'renesancia-knihtlac', title: 'Renesancia, humanizmus a kníhtlač', aka: ['Renesancia', 'Humanizmus', 'Kníhtlač', 'Gutenberg', 'Leonardo da Vinci'], subject: 'Dejepis', grade: 7, kind: 'pojmy', rec: 'mind',
 why: 'Renesancia priniesla nový pohľad na človeka, umenie aj vedu a kníhtlač ho rozšírila. Myšlienková mapa spojí myšlienky, osobnosti a vynálezy.',
 alts: [['timeline', 'Keď sa zameriavate na poradie udalostí.'], ['scene', 'Keď chcete ukázať prácu v tlačiarni.'], ['quiz', 'Na overenie.']],
