  cards: [{ q: 'Čo je dezinformácia?', a: 'Nepravdivá alebo zavádzajúca informácia šírená úmyselne.' }, { q: 'Aký je rozdiel medzi správou a komentárom?', a: 'Správa informuje o faktoch, komentár vyjadruje názor.' }, { q: 'Čo je clickbait?', a: 'Nadpis, ktorý láka na kliknutie a často preháňa.' }, { q: 'Čo urobíš, keď si správou nie si istý?', a: 'Nezdieľam ju a overím ju v iných zdrojoch.' }, { q: 'Čo je misinformácia?', a: 'Nepravdivá informácia šírená bez zlého úmyslu, omylom.', l: 2 }, { q: 'Čo je útok na osobu v diskusii?', a: 'Namiesto argumentu sa útočí na človeka, ktorý ho vyslovil.', l: 3 }],
